using System.Reflection;

namespace D47.Core.Knowledge;

/// <summary>One mission name with its family, board group and the circumstances its ending encodes; empty where it encodes none.</summary>
public sealed record MissionName(
    string Name,
    string Family,
    string Group,
    string Words,
    string State,
    string Government,
    string Economy,
    string Rank,
    string Engineer,
    string StationState,
    IReadOnlyList<string> Variants);

/// <summary>Every mission name a journal has recorded, generated by <c>tools/gen-missions.py</c>.</summary>
public static class MissionCatalogue
{
    private const string ResourceName = "D47.Core.Missions";
    private const int Columns = 11;

    private static readonly Lazy<Dictionary<string, MissionName>> Loaded =
        new(Load, LazyThreadSafetyMode.ExecutionAndPublication);

    public static IReadOnlyCollection<MissionName> All => Loaded.Value.Values;

    /// <summary>The entry for a mission name, matched without regard to case; null for a name not on the board.</summary>
    public static MissionName? Find(string? name) =>
        name is not null && Loaded.Value.TryGetValue(name, out var entry) ? entry : null;

    private static Dictionary<string, MissionName> Load()
    {
        var names = new Dictionary<string, MissionName>(StringComparer.OrdinalIgnoreCase);

        using var stream = typeof(MissionCatalogue).GetTypeInfo().Assembly.GetManifestResourceStream(ResourceName);

        if (stream is null)
        {
            return names;
        }

        using var reader = new StreamReader(stream);

        while (reader.ReadLine() is { } line)
        {
            if (line.Length == 0 || line[0] == '#')
            {
                continue;
            }

            var cells = line.Split('\t');

            if (cells.Length != Columns)
            {
                continue;
            }

            var variants = cells[10].Length == 0 ? [] : cells[10].Split(',');

            names[cells[0]] = new MissionName(
                cells[0], cells[1], cells[2], cells[3], cells[4], cells[5], cells[6], cells[7], cells[8], cells[9], variants);
        }

        return names;
    }
}
